# ============================================================================
# REAL COMPILED-SOLVER PIPELINE (mps_to_txt.py -> gpu_solver executable ->
# cpu_solve.py), integrating the actual project binaries when they're
# dropped beside this file. Every path check below is a plain existence
# check; if any required piece is missing, run_real_solver_pipeline()
# returns None and the caller falls back to the reference implementation
# -- this never crashes the app on a machine without the compiled solver
# or a CUDA GPU.
# ============================================================================

_APP_DIR = Path(os.path.dirname(os.path.abspath(__file__)))
_CONVERTER_PATH = _APP_DIR / "mps_to_txt.py"
_CPU_SOLVER_PATH = _APP_DIR / "cpu_solve.py"
_GPU_SOLVER_PATH = _APP_DIR / ("gpu_solver.exe" if os.name == "nt" else "gpu_solver")


def real_solver_available() -> bool:
    """True only if the actual compiled GPU solver binary is present and
    executable -- the one concrete, unmistakable signal that a real
    end-to-end run is possible on this machine."""
    return _GPU_SOLVER_PATH.exists()


def _correct_objective(raw_value, objective_constant: float, was_maximize: bool):
    if raw_value is None:
        return None
    total = float(raw_value) + objective_constant
    return -total if was_maximize else total


def run_real_solver_pipeline(problem: LPProblem, tol: float, max_iter: int,
                              mps_text: Optional[str] = None,
                              csv_text: Optional[str] = None,
                              console_cb=None):
    """Run the real compiled pipeline end to end:

      1. Canonicalize to the shared sparse gpu_format .txt (+ .meta.json)
         -- via mps_to_txt.py (highspy) when the user uploaded a real MPS
         file, or written directly from the already-canonical parsed LP
         problem otherwise (parse_lp_text already produces A x <= b, x>=0
         with equalities mirrored, so no highspy step is needed for that
         path).
      2. Execute the compiled gpu_solver binary on that exact file.
      3. Parse its JSON result, applying the same objective_constant /
         maximize-sign correction cpu_solve.py applies (see mps_to_txt.py
         and gpu_solver.cu's own comments on this contract).
      4. Run cpu_solve.py's solve_on_cpu() on the SAME canonicalized file
         (in-process, via the gpu_format/cpu_solve modules) so CPU and GPU
         are guaranteed to solve the identical problem.

    Returns (gpu_result, cpu_result) as SolveResult objects, or None if
    the compiled solver binary isn't present -- callers fall back to the
    NumPy/CuPy reference implementation in that case. Never raises.
    """
    if not real_solver_available():
        return None

    try:
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            gpu_input_file = tmp / "solver_input.txt"
            meta_file = gpu_input_file.with_suffix(".meta.json")
            output_file = tmp / "solver_output.json"

            objective_constant = 0.0
            was_maximize = (problem.sense == "max")
            _csv_converter = _APP_DIR / "csv_to_txt.py"

            if mps_text is not None and _CONVERTER_PATH.exists():
                mps_file = tmp / "input.mps"
                mps_file.write_text(mps_text, encoding="utf-8")
                if console_cb:
                    console_cb("Step 1/3 -- canonicalizing MPS via mps_to_txt.py (highspy)...")
                conv = subprocess.run(
                    [sys.executable, str(_CONVERTER_PATH), str(mps_file), "--out", str(gpu_input_file)],
                    capture_output=True, text=True, errors="replace", timeout=120,
                )
                if conv.returncode != 0 or not gpu_input_file.exists():
                    return None
                if meta_file.exists():
                    meta = json.loads(meta_file.read_text(encoding="utf-8"))
                    objective_constant = float(meta.get("objective_constant", 0.0))
                    was_maximize = bool(meta.get("was_maximize", False))
            elif csv_text is not None and _csv_converter.exists():
                csv_file = tmp / "input.csv"
                csv_file.write_text(csv_text, encoding="utf-8")
                if console_cb:
                    console_cb("Step 1/3 -- canonicalizing CSV via csv_to_txt.py...")
                conv = subprocess.run(
                    [sys.executable, str(_csv_converter), str(csv_file), "--out", str(gpu_input_file)],
                    capture_output=True, text=True, errors="replace", timeout=120,
                )
                if conv.returncode != 0 or not gpu_input_file.exists():
                    return None
                if meta_file.exists():
                    meta = json.loads(meta_file.read_text(encoding="utf-8"))
                    objective_constant = float(meta.get("objective_constant", 0.0))
                    was_maximize = bool(meta.get("was_maximize", False))
            elif _user_gpu_format is not None and hasattr(_user_gpu_format, "export_to_gpu_format"):
                if console_cb:
                    console_cb("Step 1/3 -- writing canonical sparse format (gpu_format.py)...")
                c_min = problem.c if problem.sense == "min" else -problem.c
                _user_gpu_format.export_to_gpu_format(
                    c_min, problem.A, problem.b, None, None, str(gpu_input_file)
                )
                meta_file.write_text(json.dumps({
                    "objective_constant": 0.0, "was_maximize": was_maximize,
                    "var_names": problem.var_names,
                }), encoding="utf-8")
            else:
                return None

            # ── Real compiled GPU solver ────────────────────────────
            if console_cb:
                console_cb(f"Step 2/3 -- launching {_GPU_SOLVER_PATH.name} (CUDA)...")
            t0 = time.perf_counter()
            try:
                proc = subprocess.run(
                    [str(_GPU_SOLVER_PATH), str(gpu_input_file), str(output_file)],
                    capture_output=True, text=True, errors="replace", timeout=120,
                )
            except (OSError, subprocess.SubprocessError):
                return None
            end_to_end_elapsed = time.perf_counter() - t0
            if console_cb and (proc.stdout or proc.stderr):
                console_cb((proc.stdout or "") + (proc.stderr or ""))
            if proc.returncode != 0 or not output_file.exists():
                return None

            gpu_json = json.loads(output_file.read_text(encoding="utf-8"))
            raw_obj = gpu_json.get("objective_value")
            objective = _correct_objective(raw_obj, objective_constant, was_maximize)
            perf = gpu_json.get("performance", {}) or {}
            gpu_compute_ms = perf.get("gpu_compute_time_ms")
            gpu_elapsed = (float(gpu_compute_ms) / 1000.0) if gpu_compute_ms is not None else end_to_end_elapsed
            gpu_result = SolveResult(
                x=np.zeros(problem.n),  # the compiled binary reports the objective/residuals, not x
                objective=objective if objective is not None else float("nan"),
                iterations=int(gpu_json.get("iterations", -1)),
                max_iterations=max_iter,
                converged=(gpu_json.get("status") == "OPTIMAL"),
                tol=tol, elapsed=gpu_elapsed,
                device=f"gpu (real backend: {_GPU_SOLVER_PATH.name}, cuSPARSE/cuBLAS FP64)",
                history_primal=[], history_dual=[], history_obj=[],
                timing_breakdown={"GPU kernel time (reported)": gpu_elapsed,
                                   "End-to-end (parse+transfer+solve)": end_to_end_elapsed},
                precision="FP64",
                final_primal_residual=gpu_json.get("primal_residual"),
                final_dual_residual=gpu_json.get("dual_residual"),
            )

            # ── Real CPU baseline, on the identical canonicalized file ──
            if console_cb:
                console_cb("Step 3/3 -- running CPU baseline (cpu_solve.py, SciPy HiGHS)...")
            cpu_result = None
            if _CPU_SOLVER_PATH.exists() and _user_gpu_format is not None:
                try:
                    import importlib
                    cpu_mod = _user_cpu_solve
                    if cpu_mod is None:
                        spec = importlib.util.spec_from_file_location("cpu_solve", str(_CPU_SOLVER_PATH))
                        cpu_mod = importlib.util.module_from_spec(spec)
                        spec.loader.exec_module(cpu_mod)
                    c_cpu, A_ub, b_ub, A_eq, b_eq = _user_gpu_format.read_gpu_format(str(gpu_input_file))
                    res, solve_time = cpu_mod.solve_on_cpu(c_cpu, A_ub, b_ub, A_eq, b_eq)
                    if bool(getattr(res, "success", False)):
                        cpu_objective = _correct_objective(float(res.fun), objective_constant, was_maximize)
                        nit = getattr(res, "nit", None)
                        cpu_result = SolveResult(
                            x=np.asarray(res.x), objective=cpu_objective,
                            iterations=int(nit) if nit is not None else -1,
                            max_iterations=max_iter, converged=True, tol=tol,
                            elapsed=float(solve_time),
                            device="cpu (real backend: cpu_solve.py, SciPy HiGHS)",
                            history_primal=[], history_dual=[], history_obj=[],
                            timing_breakdown={}, precision="FP64",
                        )
                except Exception:
                    cpu_result = None

            return gpu_result, cpu_result
    except Exception:
        return None


