def _load_real_logo():
    base = os.path.dirname(os.path.abspath(__file__))
    for name in LOGO_CANDIDATES:
        path = os.path.join(base, name)
        if os.path.isfile(path):
            try:
                raw = open(path, "r", encoding="utf-8").read()
                # Strip scripts for safety; the logo itself remains untouched.
                raw = re.sub(r"<script[\s\S]*?</script>", "", raw, flags=re.I)
                return raw
            except Exception:
                pass
    return None

_REAL_LOGO = _load_real_logo()

def logo_svg(uid: str = "") -> str:
    # Prefer a real SVG placed beside the app; otherwise use the exact embedded logo.
    if _REAL_LOGO:
        return f'<div class="cc-logo-svg" data-logo="{uid}">{_REAL_LOGO}</div>'
    return f'<img class="cc-logo-img" src="data:image/png;base64,{LOGO_PNG_B64}" alt="CUDA Crusaders">'


def asset_img(data_b64: str, alt: str = "", cls: str = "") -> str:
    return f'<img class="{cls}" src="data:image/png;base64,{data_b64}" alt="{alt}">'



