def render_navbar(active: str):
    # A persistent Home button on every stage page (Input through Results)
    # -- previously the only way back was the browser, or a button buried
    # at the bottom of the info pages; now it's always one click away.
    cols = st.columns([0.62, 1.35] + [1] * (len(STAGES) - 1))
    with cols[0]:
        if st.button("← Home", key=f"navbar_home_{active}", use_container_width=True):
            st.session_state.page = "home"
            st.rerun()
    with cols[1]:
        uid = uuid.uuid4().hex[:6]
        st.markdown(
            f"<div class='cc-topbar' style='border-bottom:none;padding:0'>"
            f"<div class='cc-brand'><div class='cc-brand-logo'>{logo_svg(uid)}</div>"
            f"<div class='cc-brand-name'>CUDA CRUSADERS</div></div></div>",
            unsafe_allow_html=True,
        )
    for i, (key, label) in enumerate(STAGES[1:], start=2):
        with cols[i]:
            disabled = key != "input" and st.session_state.problem is None
            if st.button(label, key=f"nav_{key}", use_container_width=True,
                         disabled=disabled, type="primary" if key == active else "secondary"):
                st.session_state.page = key
                st.rerun()
    st.markdown(f"<div class='cc-divider' style='margin:.35rem 0 1rem'></div>", unsafe_allow_html=True)


def stage_header(title: str, subtitle: str, key: str):
    n = STAGE_NUMBER.get(key)
    if n:
        st.markdown(
            f"<span class='cc-stage-label'>{title}</span>"
            f"<span class='cc-stage-count'>{n:02d} / 06</span>",
            unsafe_allow_html=True,
        )
    st.markdown(f"### {subtitle}")


# ============================================================================
# LP PARSING (self-contained reference parser; used unless the real
# gpu_format module is present and exposes a compatible reader)
# ============================================================================

TERM_RE = re.compile(r"([+-]?\s*\d*\.?\d*)\s*\*?\s*([A-Za-z_][A-Za-z0-9_]*)")


@dataclass
class LPProblem:
    sense: str                 # "max" or "min"
    var_names: list
    c: np.ndarray               # objective coefficients, aligned to var_names, in MAX sense
    A: "sparse.csr_matrix"
    b: np.ndarray
    row_labels: list = field(default_factory=list)
    source_text: str = ""
    source_format: str = "LP"   # "MPS" / "LP" / "CSV" -- which uploaded format this came from
    objective_is_absent: bool = False  # CSV only: True if the CSV had no objective rows

    @property
    def m(self):
        return self.A.shape[0]

    @property
    def n(self):
        return self.A.shape[1]

    @property
    def nnz(self):
        return int(self.A.nnz)

    @property
    def sparsity(self):
        total = self.m * self.n
        return 1.0 - (self.nnz / total) if total else 0.0


def _parse_linear_expr(expr: str, var_index: dict, var_names: list) -> dict:
    expr = expr.replace("−", "-").strip()
    coeffs = {}
    for raw_coef, var in TERM_RE.findall(expr):
        var = var.strip()
        if not var:
            continue
        raw_coef = raw_coef.replace(" ", "")
        if raw_coef in ("", "+"):
            coef = 1.0
        elif raw_coef == "-":
            coef = -1.0
        else:
            coef = float(raw_coef)
        if var not in var_index:
            var_index[var] = len(var_names)
            var_names.append(var)
        coeffs[var] = coeffs.get(var, 0.0) + coef
    return coeffs


def parse_lp_text(text: str) -> LPProblem:
    """Parses a small, readable LP text format:

        Maximize 3x1 + 2x2 + 5x3
        Subject to:
        x1 + 2x2 + x3 <= 10
        2x1 + x2 <= 8
        x1 + x3 <= 6
        x1, x2, x3 >= 0
    """
    if not text or not text.strip():
        raise ValueError("Empty problem text.")

    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    var_index: dict = {}
    var_names: list = []

    sense = "max"
    obj_expr = None
    constraint_lines = []
    started_constraints = False

    for ln in lines:
        low = ln.lower()
        if low.startswith("maximize") or low.startswith("max"):
            sense = "max"
            obj_expr = re.sub(r"(?i)^maximize|^max", "", ln).strip()
            continue
        if low.startswith("minimize") or low.startswith("min"):
            sense = "min"
            obj_expr = re.sub(r"(?i)^minimize|^min", "", ln).strip()
            continue
        if low.startswith("subject to") or low == "s.t.":
            started_constraints = True
            continue
        if re.search(r">=\s*0|>=0", ln) and not re.search(r"[<>=]=.*\d.*[a-zA-Z]", ln.split(">=")[-1]):
            # a pure non-negativity bound line like "x1, x2, x3 >= 0" -- skip
            lhs = ln.split(">=")[0]
            if all(TERM_RE.match(t.strip()) for t in lhs.split(",") if t.strip()):
                if re.fullmatch(r"[A-Za-z0-9_,\s]+", lhs):
                    continue
        constraint_lines.append(ln)
        started_constraints = True

    if obj_expr is None:
        raise ValueError("Could not find an objective line starting with 'Maximize' or 'Minimize'.")

    obj_coeffs = _parse_linear_expr(obj_expr, var_index, var_names)

    rows = []
    row_labels = []
    for idx, ln in enumerate(constraint_lines, start=1):
        m = re.search(r"(<=|>=|=)", ln)
        if not m:
            continue
        op = m.group(1)
        lhs, rhs = ln.split(op, 1)
        lhs_coeffs = _parse_linear_expr(lhs, var_index, var_names)
        try:
            rhs_val = float(rhs.strip())
        except ValueError:
            continue
        if not lhs_coeffs:
            continue
        rows.append((lhs_coeffs, op, rhs_val))
        row_labels.append(f"Constraint {idx}: {ln.strip()}")

    if not rows:
        raise ValueError("No parsable constraints found.")

    n = len(var_names)
    data, indices, indptr = [], [], [0]
    b = []
    for lhs_coeffs, op, rhs_val in rows:
        sign = 1.0
        if op == ">=":
            sign = -1.0
        row_pairs = sorted(
            ((var_index[v], coef * sign) for v, coef in lhs_coeffs.items()),
            key=lambda p: p[0],
        )
        for j, val in row_pairs:
            indices.append(j)
            data.append(val)
        indptr.append(len(data))
        b.append(rhs_val * sign)
        if op == "=":
            # split equality into <= and >= to keep a single-form A x <= b
            row_pairs2 = sorted(
                ((var_index[v], -coef) for v, coef in lhs_coeffs.items()),
                key=lambda p: p[0],
            )
            for j, val in row_pairs2:
                indices.append(j)
                data.append(val)
            indptr.append(len(data))
            b.append(-rhs_val)
            row_labels.append(row_labels[-1] + "  (equality, mirrored)")

    A = sparse.csr_matrix((data, indices, indptr), shape=(len(indptr) - 1, n))
    b_arr = np.array(b, dtype=float)

    c = np.zeros(n)
    for v, coef in obj_coeffs.items():
        c[var_index[v]] = coef

    return LPProblem(sense=sense, var_names=var_names, c=c, A=A, b=b_arr,
                      row_labels=row_labels, source_text=text)


def parse_mps_text(text: str) -> LPProblem:
    """Free-format MPS reader (ROWS / COLUMNS / RHS / BOUNDS).

    Rewritten to be O(rows + cols + nnz) throughout, for real benchmark
    files (tens of thousands of rows/cols) rather than only tiny demo
    problems. The previous version built each constraint row with
    `{v: col_data[v][rname] for v in var_order if ...}` -- a scan over
    EVERY variable for EVERY row, i.e. O(rows x cols): on a file like
    cre-b.mps (~9.6k rows x ~72k cols) that's ~700 million pure-Python
    dict lookups, which is what actually made large uploads look frozen
    rather than slow. This version collects (row, col, value) triplets
    once while scanning COLUMNS and lets scipy's C-level sparse
    construction do the grouping/summation and the row slicing, matching
    the original's semantics (duplicate entries summed, same row
    ordering: inequalities, then E-row mirrors, then bound rows).
    """
    lines = [ln.rstrip() for ln in text.splitlines() if ln.strip() and not ln.strip().startswith("*")]
    section = None
    row_types = {}    # name -> N/L/G/E
    row_order = []    # row names in file (ROWS section) order
    row_index = {}    # populated once the ROWS section is fully read
    obj_row = None
    var_order = []
    var_index = {}
    rhs = {}
    bounds_lower = {}
    bounds_upper = {}
    trip_rows, trip_cols, trip_vals = [], [], []

    for ln in lines:
        head = ln.split()[0].upper() if ln[0] not in (" ", "\t") else None
        if head in ("NAME", "ROWS", "COLUMNS", "RHS", "RANGES", "BOUNDS", "ENDATA"):
            section = head
            if section == "COLUMNS" and not row_index:
                # ROWS always precedes COLUMNS in valid MPS -- build the
                # name->index map exactly once, not per COLUMNS line.
                row_index = {r: i for i, r in enumerate(row_order)}
            continue
        parts = ln.split()
        if section == "ROWS":
            rtype, rname = parts[0].upper(), parts[1]
            row_types[rname] = rtype
            row_order.append(rname)
            if rtype == "N" and obj_row is None:
                obj_row = rname
        elif section == "COLUMNS":
            if len(parts) < 3:
                continue
            colname = parts[0]
            ci = var_index.get(colname)
            if ci is None:
                ci = len(var_order)
                var_index[colname] = ci
                var_order.append(colname)
            for i in range(1, len(parts) - 1, 2):
                ri = row_index.get(parts[i])
                if ri is None:
                    continue  # tolerate a stray/unknown row reference
                trip_rows.append(ri)
                trip_cols.append(ci)
                trip_vals.append(float(parts[i + 1]))
        elif section == "RHS":
            for i in range(1, len(parts) - 1, 2):
                rhs[parts[i]] = float(parts[i + 1])
        elif section == "BOUNDS":
            btype = parts[0].upper()
            colname = parts[2]
            val = float(parts[3]) if len(parts) > 3 else 0.0
            if btype == "UP":
                bounds_upper[colname] = val
            elif btype == "LO":
                bounds_lower[colname] = val
            elif btype == "FX":
                bounds_lower[colname] = val
                bounds_upper[colname] = val

    if obj_row is None or not var_order:
        raise ValueError("MPS file missing an objective (N) row or COLUMNS section.")

    n = len(var_order)
    m_full = len(row_order)

    # One sparse construction for the whole matrix (objective row
    # included); scipy sums duplicate (row, col) entries in C, matching
    # the original dict-based accumulation without a Python loop per nnz.
    A_full = sparse.coo_matrix((trip_vals, (trip_rows, trip_cols)), shape=(m_full, n)).tocsr()
    A_full.sum_duplicates()

    c = np.asarray(A_full[row_index[obj_row], :].todense()).reshape(-1)

    ineq_positions = np.array([i for i, r in enumerate(row_order) if row_types[r] != "N"], dtype=np.int64)
    ineq_names = [row_order[i] for i in ineq_positions]
    A_ineq = A_full[ineq_positions, :] if len(ineq_positions) else sparse.csr_matrix((0, n))

    signs = np.array([-1.0 if row_types[r] == "G" else 1.0 for r in ineq_names])
    rhs_vals = np.array([rhs.get(r, 0.0) for r in ineq_names])
    A_signed = A_ineq.multiply(signs[:, None]).tocsr() if len(ineq_names) else A_ineq
    b_signed = rhs_vals * signs
    row_labels = [f"Row {r}" for r in ineq_names]

    eq_pos = [i for i, r in enumerate(ineq_names) if row_types[r] == "E"]
    if eq_pos:
        A_signed = sparse.vstack([A_signed, -A_ineq[eq_pos, :]], format="csr")
        b_signed = np.concatenate([b_signed, -rhs_vals[eq_pos]])
        row_labels += [f"Row {ineq_names[i]}_mirror" for i in eq_pos]

    # Variable-bound rows (x <= ub, -x <= -lb), each built as one small
    # sparse block instead of one Python-level row per bound.
    extra_blocks, extra_b, extra_labels = [], [], []
    ub_vars = [v for v in var_order if v in bounds_upper]
    if ub_vars:
        cols_ = np.array([var_index[v] for v in ub_vars])
        extra_blocks.append(sparse.coo_matrix(
            (np.ones(len(ub_vars)), (np.arange(len(ub_vars)), cols_)), shape=(len(ub_vars), n)))
        extra_b.append(np.array([bounds_upper[v] for v in ub_vars]))
        extra_labels += [f"{v}<=ub" for v in ub_vars]
    lb_vars = [v for v in var_order if v in bounds_lower and bounds_lower[v] != 0.0]
    if lb_vars:
        cols_ = np.array([var_index[v] for v in lb_vars])
        extra_blocks.append(sparse.coo_matrix(
            (-np.ones(len(lb_vars)), (np.arange(len(lb_vars)), cols_)), shape=(len(lb_vars), n)))
        extra_b.append(np.array([-bounds_lower[v] for v in lb_vars]))
        extra_labels += [f"{v}>=lb" for v in lb_vars]
    if extra_blocks:
        A_signed = sparse.vstack([A_signed] + extra_blocks, format="csr")
        b_signed = np.concatenate([b_signed] + extra_b)
        row_labels += extra_labels

    # The raw MPS text can be tens of MB; nothing in the UI reads it back,
    # so it isn't kept in session state for large uploads.
    kept_source = text if len(text) <= 200_000 else ""
    return LPProblem(sense="min", var_names=var_order, c=c, A=A_signed.tocsr(),
                      b=np.asarray(b_signed, dtype=float),
                      row_labels=row_labels, source_text=kept_source)


CSV_REQUIRED_COLUMNS = ["type", "row", "col", "value", "rhs", "sense"]
CSV_VALID_TYPES = {"constraint", "objective"}
CSV_SENSE_ALIASES = {"<=": "<=", "le": "<=", ">=": ">=", "ge": ">=", "=": "=", "==": "=", "eq": "="}


def _csv_float(raw, line_no, field_name):
    raw = (raw or "").strip()
    if raw == "":
        raise ValueError(f"Missing value for '{field_name}' on CSV row {line_no}.")
    try:
        return float(raw)
    except ValueError:
        raise ValueError(f"Invalid numeric value for '{field_name}' on CSV row {line_no}: {raw!r}") from None


def _csv_index(raw, line_no, field_name):
    raw = (raw or "").strip()
    if raw == "":
        raise ValueError(f"Missing value for '{field_name}' on CSV row {line_no}.")
    try:
        val = int(raw)
    except ValueError:
        raise ValueError(f"Invalid index for '{field_name}' on CSV row {line_no}: {raw!r} (must be a non-negative integer)") from None
    if val < 0:
        raise ValueError(f"Invalid index for '{field_name}' on CSV row {line_no}: {val} (indices must be >= 0)")
    return val


def parse_csv_text(text: str) -> LPProblem:
    """Parses the type,row,col,value,rhs,sense CSV schema into an LPProblem,
    using the SAME canonical A x <= b, x >= 0 representation parse_lp_text()
    and parse_mps_text() produce (equalities mirrored into a <= pair, >=
    rows sign-flipped) -- so every downstream stage (GPU prep, PDHG, CPU
    benchmark, analytics) stays completely format-independent.

    CSV objective rows are interpreted directly as MINIMIZE c^T x
    coefficients (the same convention gpu_format.py's minimize-only format
    uses). If the CSV has no 'objective' rows at all, the objective is left
    all-zero (never fabricated) and problem.objective_is_absent is set so
    the caller can warn the user.

        type,row,col,value,rhs,sense
        objective,,0,3,,
        constraint,0,0,1,10,<=
    """
    if not text or not text.strip():
        raise ValueError("CSV file is empty.")

    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV file is empty.") from None

    header_norm = [h.strip().lower() for h in header]
    missing = [c for c in CSV_REQUIRED_COLUMNS if c not in header_norm]
    if missing:
        raise ValueError(f"CSV is missing required column(s): {', '.join(missing)}")
    col_idx = {c: header_norm.index(c) for c in CSV_REQUIRED_COLUMNS}

    constraints: dict = {}
    objective: dict = {}
    max_col = -1
    any_data_row = False

    for line_no, fields in enumerate(reader, start=2):
        if not fields or all((f or "").strip() == "" for f in fields):
            continue
        if len(fields) < len(header):
            raise ValueError(f"Malformed CSV row {line_no}: expected {len(header)} fields, got {len(fields)}.")
        any_data_row = True

        row_type = (fields[col_idx["type"]] or "").strip().lower()
        if row_type not in CSV_VALID_TYPES:
            raise ValueError(
                f"Invalid 'type' value on CSV row {line_no}: {fields[col_idx['type']]!r} "
                f"(expected 'constraint' or 'objective')."
            )

        col = _csv_index(fields[col_idx["col"]], line_no, "col")
        value = _csv_float(fields[col_idx["value"]], line_no, "value")
        max_col = max(max_col, col)

        if row_type == "objective":
            objective[col] = objective.get(col, 0.0) + value
            continue

        row = _csv_index(fields[col_idx["row"]], line_no, "row")
        rhs = _csv_float(fields[col_idx["rhs"]], line_no, "rhs")
        sense_raw = (fields[col_idx["sense"]] or "").strip().lower()
        sense = CSV_SENSE_ALIASES.get(sense_raw)
        if sense is None:
            raise ValueError(
                f"Invalid constraint sense on CSV row {line_no}: {fields[col_idx['sense']]!r} "
                f"(expected one of '<=', '>=', '=')."
            )
        entry = constraints.setdefault(row, {"coeffs": {}, "rhs": rhs, "sense": sense})
        if entry["rhs"] != rhs:
            raise ValueError(
                f"Inconsistent rhs for constraint row {row} on CSV row {line_no}: "
                f"{entry['rhs']!r} vs {rhs!r} (every line for the same row must agree)."
            )
        if entry["sense"] != sense:
            raise ValueError(
                f"Inconsistent sense for constraint row {row} on CSV row {line_no}: "
                f"{entry['sense']!r} vs {sense!r} (every line for the same row must agree)."
            )
        entry["coeffs"][col] = entry["coeffs"].get(col, 0.0) + value

    if not any_data_row:
        raise ValueError("CSV has a header but no data rows.")
    if not constraints:
        raise ValueError("CSV must contain at least one constraint row (type=constraint).")

    row_ids = sorted(constraints.keys())
    expected = list(range(len(row_ids)))
    if row_ids != expected:
        found_missing = sorted(set(expected) - set(row_ids))
        raise ValueError(
            f"CSV is missing constraint row(s) {found_missing} -- 'row' indices must be "
            f"a contiguous 0-based range with no gaps (found rows {row_ids})."
        )

    n = max(max_col + 1, (max(objective.keys()) + 1) if objective else 0)
    if n == 0:
        raise ValueError("CSV has no variable columns.")
    var_names = [f"x{j}" for j in range(n)]

    data, indices, indptr = [], [], [0]
    b = []
    row_labels = []
    for row in row_ids:
        entry = constraints[row]
        sense = entry["sense"]
        sign = -1.0 if sense == ">=" else 1.0
        pairs = sorted(((c, v * sign) for c, v in entry["coeffs"].items()), key=lambda p: p[0])
        for j, val in pairs:
            indices.append(j); data.append(val)
        indptr.append(len(data))
        b.append(entry["rhs"] * sign)
        row_labels.append(f"CSV constraint row {row} ({sense})")
        if sense == "=":
            pairs2 = sorted(((c, -v) for c, v in entry["coeffs"].items()), key=lambda p: p[0])
            for j, val in pairs2:
                indices.append(j); data.append(val)
            indptr.append(len(data))
            b.append(-entry["rhs"])
            row_labels.append(f"CSV constraint row {row} (=, mirrored)")

    A = sparse.csr_matrix((data, indices, indptr), shape=(len(indptr) - 1, n))
    b_arr = np.array(b, dtype=float)

    c = np.zeros(n)
    for col, val in objective.items():
        c[col] = val

    kept_source = text if len(text) <= 200_000 else ""
    problem = LPProblem(sense="min", var_names=var_names, c=c, A=A, b=b_arr,
                         row_labels=row_labels, source_text=kept_source,
                         source_format="CSV", objective_is_absent=(len(objective) == 0))
    return problem


# ============================================================================
# REFERENCE PDHG SOLVER (real algorithm, real measured timing per stage)
# ============================================================================

@dataclass
class SolveResult:
    x: np.ndarray
    objective: float
    iterations: int
    max_iterations: int
    converged: bool
    tol: float
    elapsed: float
    device: str
    history_primal: list
    history_dual: list
    history_obj: list
    timing_breakdown: dict
    precision: str
    # Populated only by the real compiled-solver pipeline, which reports a
    # single final residual rather than a per-iteration history; the
    # reference PDHG path leaves these None and uses history_primal/_dual
    # instead (see render_metric_boxes call sites, which check both).
    final_primal_residual: Optional[float] = None
    final_dual_residual: Optional[float] = None


def reference_pdhg(problem: LPProblem, tol: float, max_iter: int, device: str = "cpu",
                    progress_cb=None) -> SolveResult:
    """A genuine Chambolle-Pock / PDHG solver for:
        minimize   c^T x
        subject to A x <= b, x >= 0
    Internally always minimizes; a Maximize problem is solved as -c.
    Every timing figure below is wall-clock measured around the actual
    NumPy (or CuPy, if `device == 'gpu'` and CuPy is available) operation.
    """
    xp = np
    use_gpu = False
    if device == "gpu" and _HAVE_CUPY:
        xp = _cupy
        use_gpu = True

    A = problem.A
    m, n = A.shape
    c = problem.c if problem.sense == "min" else -problem.c
    b = problem.b

    A_dense_ok = (m * n) <= 4_000_000
    if use_gpu:
        A_gpu = _cupy.sparse.csr_matrix(A) if hasattr(_cupy, "sparse") else xp.asarray(A.toarray())
        c_x = xp.asarray(c)
        b_x = xp.asarray(b)
    else:
        A_gpu = A
        c_x = c
        b_x = b

    # crude Lipschitz estimate for step sizes: ||A||_2 ~ sqrt(||A||_1 * ||A||_inf)
    row_norms = np.sqrt(A.multiply(A).sum(axis=1)).A.ravel() if hasattr(A, "multiply") else np.linalg.norm(A, axis=1)
    col_norms = np.sqrt(A.multiply(A).sum(axis=0)).A.ravel() if hasattr(A, "multiply") else np.linalg.norm(A, axis=0)
    row_max = float(row_norms.max()) if row_norms.size else 1.0
    col_max = float(col_norms.max()) if col_norms.size else 1.0
    op_norm_est = float(np.sqrt(max(row_max, 1e-9) * max(col_max, 1e-9))) or 1.0
    tau = 1.0 / (op_norm_est + 1e-9)
    sigma = 1.0 / (op_norm_est + 1e-9)

    x = xp.zeros(n)
    x_bar = xp.zeros(n)
    y = xp.zeros(m)

    timing = {"A^T . y (dual->primal grad)": 0.0, "primal update": 0.0,
              "A . x_bar (primal->dual grad)": 0.0, "dual update": 0.0,
              "convergence check": 0.0}
    hist_p, hist_d, hist_obj = [], [], []
    converged = False
    it = 0
    t_start = time.perf_counter()
    sample_every = max(1, max_iter // 400)

    for it in range(1, max_iter + 1):
        t0 = time.perf_counter()
        grad = A_gpu.T.dot(y)
        t1 = time.perf_counter()
        timing["A^T . y (dual->primal grad)"] += t1 - t0

        x_new = xp.maximum(x - tau * (c_x + grad), 0.0)
        x_bar = 2 * x_new - x
        t2 = time.perf_counter()
        timing["primal update"] += t2 - t1

        Ax = A_gpu.dot(x_bar)
        t3 = time.perf_counter()
        timing["A . x_bar (primal->dual grad)"] += t3 - t2

        y_new = xp.maximum(y + sigma * (Ax - b_x), 0.0)
        t4 = time.perf_counter()
        timing["dual update"] += t4 - t3

        if it % sample_every == 0 or it == 1:
            resid_primal = float(xp.linalg.norm(xp.maximum(A_gpu.dot(x_new) - b_x, 0.0))) if use_gpu else float(
                np.linalg.norm(np.maximum(A.dot(x_new if not use_gpu else x_new.get()) - b, 0.0)))
            resid_dual = float(xp.linalg.norm(y_new - y))
            obj_val = float(c_x @ x_new) if not use_gpu else float((c_x @ x_new).get())
            hist_p.append(resid_primal)
            hist_d.append(resid_dual)
            hist_obj.append(obj_val if problem.sense == "min" else -obj_val)
            if progress_cb:
                progress_cb(it, max_iter, resid_primal, resid_dual)
            t5 = time.perf_counter()
            timing["convergence check"] += t5 - t4
            if resid_primal < tol and resid_dual < tol:
                x, y = x_new, y_new
                converged = True
                break
        x, y = x_new, y_new

    elapsed = time.perf_counter() - t_start
    x_final = x.get() if use_gpu else x
    obj_min = float(c @ x_final)
    objective = obj_min if problem.sense == "min" else -obj_min

    return SolveResult(
        x=np.asarray(x_final), objective=objective, iterations=it, max_iterations=max_iter,
        converged=converged, tol=tol, elapsed=elapsed,
        device=("gpu (CuPy CUDA kernels)" if use_gpu else "cpu (NumPy reference)"),
        history_primal=hist_p, history_dual=hist_d, history_obj=hist_obj,
        timing_breakdown=timing, precision="FP32" if not use_gpu else "FP32",
    )


def reference_cpu_solve(problem: LPProblem, tol: float, max_iter: int) -> SolveResult:
    """CPU baseline using SciPy's HiGHS simplex/interior-point solver --
    a genuinely different, independent algorithm run on the exact same
    parsed problem, for a fair benchmark."""
    c = problem.c if problem.sense == "min" else -problem.c
    t0 = time.perf_counter()
    res = linprog(c, A_ub=problem.A, b_ub=problem.b, bounds=(0, None), method="highs")
    elapsed = time.perf_counter() - t0
    obj_min = res.fun if res.success else float("nan")
    objective = obj_min if problem.sense == "min" else -obj_min
    nit = getattr(res, "nit", None)
    return SolveResult(
        x=res.x if res.success else np.zeros(problem.n),
        objective=objective, iterations=int(nit) if nit is not None else -1,
        max_iterations=max_iter, converged=bool(res.success), tol=tol, elapsed=elapsed,
        device="cpu (SciPy HiGHS)", history_primal=[], history_dual=[], history_obj=[],
        timing_breakdown={}, precision="FP64",
    )


# ============================================================================
# REAL BACKEND INTEGRATION (best-effort; falls back to the reference
# implementations above on any mismatch -- never crashes the app)
# ============================================================================

def try_real_cpu_solve(problem: LPProblem, tol: float, max_iter: int) -> Optional[SolveResult]:
    """If a real cpu_solve module was found beside this file (see the import
    probing near the top), actually call it instead of the built-in
    reference solver. Several common entry-point names/signatures are
    tried; the first one that returns a recognizable result wins. Returns
    None (never raises) if no real module is present or none of the calls
    succeed, so the caller can cleanly fall back to reference_cpu_solve."""
    if _user_cpu_solve is None:
        return None
    c = problem.c if problem.sense == "min" else -problem.c
    for fn_name in ("solve_on_cpu", "solve", "cpu_solve", "run"):
        fn = getattr(_user_cpu_solve, fn_name, None)
        if not callable(fn):
            continue
        try:
            t0 = time.perf_counter()
            out = fn(c, problem.A, problem.b, None, None)
            fallback_elapsed = time.perf_counter() - t0
            res, solve_time = (out if isinstance(out, tuple) and len(out) == 2
                                else (out, fallback_elapsed))
            if not bool(getattr(res, "success", False)):
                continue
            obj_min = float(res.fun)
            objective = obj_min if problem.sense == "min" else -obj_min
            nit = getattr(res, "nit", None)
            return SolveResult(
                x=np.asarray(res.x), objective=objective,
                iterations=int(nit) if nit is not None else -1,
                max_iterations=max_iter, converged=True, tol=tol,
                elapsed=float(solve_time),
                device=f"cpu (real backend: cpu_solve.{fn_name})",
                history_primal=[], history_dual=[], history_obj=[],
                timing_breakdown={}, precision="FP64",
            )
        except Exception:
            continue
    return None


def try_real_gpu_solve(problem: LPProblem, tol: float, max_iter: int) -> Optional[SolveResult]:
    """Mirror of try_real_cpu_solve for a real GPU solver module, if one was
    detected. Real GPU LP solvers are often a compiled kernel/executable
    rather than a plain Python function, so this is deliberately best
    effort: any signature mismatch or exception simply falls back to the
    reference PDHG implementation (which itself already runs on real CuPy
    CUDA kernels when a GPU is available)."""
    if _user_gpu_solve is None:
        return None
    c = problem.c if problem.sense == "min" else -problem.c
    for fn_name in ("solve", "gpu_solve", "pdhg_gpu", "run", "solve_on_gpu"):
        fn = getattr(_user_gpu_solve, fn_name, None)
        if not callable(fn):
            continue
        try:
            t0 = time.perf_counter()
            out = fn(c, problem.A, problem.b, tol=tol, max_iter=max_iter)
            fallback_elapsed = time.perf_counter() - t0
            res, solve_time = (out if isinstance(out, tuple) and len(out) == 2
                                else (out, fallback_elapsed))
            if not bool(getattr(res, "success", False)):
                continue
            obj_min = float(res.fun)
            objective = obj_min if problem.sense == "min" else -obj_min
            nit = getattr(res, "nit", None)
            return SolveResult(
                x=np.asarray(res.x), objective=objective,
                iterations=int(nit) if nit is not None else -1,
                max_iterations=max_iter, converged=True, tol=tol,
                elapsed=float(solve_time),
                device=f"gpu (real backend: {getattr(_user_gpu_solve, '__name__', 'gpu_solve')}.{fn_name})",
                history_primal=[], history_dual=[], history_obj=[],
                timing_breakdown={}, precision="FP32",
            )
        except Exception:
            continue
    return None


# ============================================================================
# SYSTEM / GPU TELEMETRY (real only; "Unavailable" otherwise)
# ============================================================================

def cpu_info() -> dict:
    info = {
        "Processor": platform.processor() or platform.machine() or "Unavailable",
        "Logical Cores": os.cpu_count() or "Unavailable",
    }
    if _HAVE_PSUTIL:
        info["Physical Cores"] = psutil.cpu_count(logical=False) or "Unavailable"
        info["Threads"] = psutil.cpu_count(logical=True) or "Unavailable"
    else:
        info["Physical Cores"] = "Unavailable"
        info["Threads"] = os.cpu_count() or "Unavailable"
    return info


def gpu_static_info() -> dict:
    info = {"GPU Name": "Unavailable", "CUDA Version": "Unavailable", "Backend": "Unavailable"}
    try:
        out = subprocess.run(
            ["nvidia-smi", "--query-gpu=name,driver_version", "--format=csv,noheader"],
            capture_output=True, text=True, timeout=2,
        )
        if out.returncode == 0 and out.stdout.strip():
            name, driver = [s.strip() for s in out.stdout.strip().splitlines()[0].split(",")]
            info["GPU Name"] = name
            info["Driver Version"] = driver
    except Exception:
        pass
    if _HAVE_CUPY:
        try:
            v = _cupy.cuda.runtime.runtimeGetVersion()
            info["CUDA Version"] = f"{v // 1000}.{(v % 1000) // 10}"
            info["Backend"] = "CuPy (real CUDA kernels)"
        except Exception:
            pass
    else:
        info["Backend"] = "Reference NumPy (CuPy not installed in this environment)"
    return info


def sample_gpu_utilization(duration_s: float, interval_s: float = 0.08) -> list:
    """Best-effort GPU utilization sampling via nvidia-smi. Returns [] if unavailable."""
    samples = []
    t_end = time.time() + duration_s
    try:
        subprocess.run(["nvidia-smi", "-L"], capture_output=True, timeout=1, check=True)
    except Exception:
        return samples
    while time.time() < t_end:
        try:
            out = subprocess.run(
                ["nvidia-smi", "--query-gpu=utilization.gpu", "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=1,
            )
            if out.returncode == 0 and out.stdout.strip():
                samples.append(float(out.stdout.strip().splitlines()[0]))
        except Exception:
            break
        time.sleep(interval_s)
    return samples


