# ============================================================================
# ANIMATION: LP -> COEFFICIENTS -> MATRIX (the centerpiece visualization)
# ============================================================================

def render_lp_to_matrix(problem: LPProblem, max_animated_rows: int = 4):
    """Exam-style LP -> matrix view: equations on paper, then A and b in standard bracket notation."""
    A=problem.A.tocsr(); m,n=A.shape
    show_rows=min(5,m); show_cols=min(10,n)
    def scalar(v):
        # Safely convert Python/NumPy/SciPy scalar-like values, including 1-element arrays.
        a = np.asarray(v)
        if a.size == 0:
            return 0.0
        if a.size == 1:
            return float(a.ravel()[0])
        # Never pass a multi-element ndarray to float(). For display formatting,
        # use the first element rather than crashing the entire Streamlit page.
        return float(a.ravel()[0])

    def fmt(v):
        x = scalar(v)
        if abs(x-round(x))<1e-9: return str(int(round(x)))
        return f"{x:.3g}"
    objective=" + ".join([f"{fmt(c)}{v}" for v,c in zip(problem.var_names,problem.c) if abs(float(c))>1e-12]) or "0"
    eq_lines=[]
    for r in range(show_rows):
        terms=[]
        for j in range(n):
            v=float(A[r,j])
            if abs(v)>1e-12:
                var=problem.var_names[j]
                coef=fmt(abs(v)); sign='+' if v>0 else '-'
                term=("" if coef=='1' else coef)+var
                terms.append((sign,term))
        line=""
        for k,(sg,term) in enumerate(terms):
            if k==0: line=term if sg=='+' else '-'+term
            else: line += f" {sg} {term}"
        eq_lines.append(f"{line} ≤ {fmt(problem.b[r])}")
    eq_html=''.join(f'<div class="exam-eq">{_html.escape(x)}</div>' for x in eq_lines)
    rows=[]
    for r in range(show_rows):
        vals=[fmt(A[r,j]) for j in range(show_cols)]
        if n>show_cols: vals.append('⋯')
        rows.append('<div class="matrix-row">' + ''.join(f'<span>{_html.escape(v)}</span>' for v in vals) + '</div>')
    if m>show_rows:
        rows.append('<div class="matrix-more">⋮</div>')
    rhs=[fmt(problem.b[r]) for r in range(show_rows)]
    rhs_html=''.join(f'<div class="rhs-row">{_html.escape(v)}</div>' for v in rhs)
