    stages = ["A · ȳ", "DUAL UPDATE", "Aᵀ · x", "PRIMAL UPDATE", "CONVERGENCE CHECK"]
    stages_json = json.dumps(stages)
    active_idx = (current_iter // 3) % len(stages) if running else -1
    html = f"""
    <div style="font-family:Inter,sans-serif; display:flex; align-items:center; justify-content:center;
         gap:10px; flex-wrap:wrap; padding:6px 0;">
      <div id="loopwrap" style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;"></div>
    </div>
    <script>
      const STAGES = {stages_json};
      const ACTIVE = {active_idx};
      const wrap = document.getElementById('loopwrap');
      STAGES.forEach((s, i) => {{
        const box = document.createElement('div');
        const isActive = (i === ACTIVE);
        box.style.cssText = `padding:9px 14px; border-radius:8px; font-weight:700; font-size:0.82rem;
          letter-spacing:0.02em; border:1.5px solid ${{isActive ? '{ROYAL_BLUE}' : '{BORDER}'}};
          color: ${{isActive ? '{ROYAL_BLUE}' : '{SLATE}'}};
          background: ${{isActive ? 'rgba(41,85,214,0.10)' : '#F8FAFD'}};
          transform: ${{isActive ? 'scale(1.06)' : 'scale(1)'}};
          transition: all .4s ease;`;
        box.textContent = s;
        wrap.appendChild(box);
        if (i < STAGES.length - 1) {{
          const arrow = document.createElement('div');
          arrow.style.cssText = 'color:{SLATE};font-size:0.9rem;';
          arrow.textContent = '→';
          wrap.appendChild(arrow);
        }}
      }});
      if ({str(running).lower()}) {{
        const loopBack = document.createElement('div');
        loopBack.style.cssText = 'color:{VIOLET};font-size:1rem;font-weight:700;';
        loopBack.textContent = '↺';
        wrap.appendChild(loopBack);
      }}
    </script>
    """
    components.html(html, height=70)


