def render_iteration_graph(values: list, y_label: str, color: str = ROYAL_BLUE, log_scale: bool = True, height: int = 280):
    if not values:
        st.markdown("<div class='cc-muted'>No iteration history available.</div>",unsafe_allow_html=True); return
    if not _HAVE_MPL:
        st.line_chart(values, height=height)
        return
    vals=np.asarray(values,dtype=float); x=np.arange(1,len(vals)+1)
    fig,ax=plt.subplots(figsize=(11,3.7)); ax.plot(x,vals,marker='o',markersize=3.5,linewidth=1.6,color=color,alpha=.9)
    if log_scale: ax.set_yscale('log')
    ax.set_xlabel('Recorded iteration points',color=NAVY); ax.set_ylabel(y_label,color=NAVY)
    ax.grid(True,axis='y',alpha=.18); ax.set_facecolor('white'); fig.patch.set_facecolor('white')
    ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
    ax.spines['left'].set_color(BORDER); ax.spines['bottom'].set_color(BORDER)
    ax.tick_params(colors=SLATE,labelsize=8); fig.tight_layout(); st.pyplot(fig,use_container_width=True); plt.close(fig)


def render_sparsity_heatmap(problem: LPProblem, height: int = 340):
    """A genuine density heat map of the constraint matrix's sparsity pattern.

    The matrix is never densified. Instead the real (row, col) coordinates of
    every non-zero entry are binned into a coarse grid (numpy.histogram2d),
    and each cell's color encodes exactly how many real non-zero entries fall
    in that block -- this is a proper heat map (color = measured density),
    not a uniform-color scatter of dots. Matrix dimensions and NNZ shown are
    always exact; only the binning resolution is capped, for readability and
    to keep rendering memory-safe on very large matrices.
    """
    if not _HAVE_MPL:
        st.info("Matplotlib is unavailable; matrix heatmap cannot be rendered.")
        return

    A = problem.A.tocsr()
    m, n = A.shape
    nnz = int(A.nnz)

    coo = A.tocoo(copy=False)
    rows = np.asarray(coo.row)
    cols = np.asarray(coo.col)

    bins_r = max(1, min(m, 140))
    bins_c = max(1, min(n, 140))
    if nnz > 0:
        density, _yedges, _xedges = np.histogram2d(
            rows, cols, bins=[bins_r, bins_c], range=[[0, max(m, 1)], [0, max(n, 1)]]
        )
    else:
        density = np.zeros((bins_r, bins_c))

    fig, ax = plt.subplots(figsize=(11, 4.4), dpi=90)
    mesh = ax.imshow(
        density, origin='upper', aspect='auto', cmap='Blues',
        extent=[0, n, m, 0], interpolation='nearest',
    )
    cbar = fig.colorbar(mesh, ax=ax, pad=0.015)
    cbar.set_label('Non-zero entries per cell', color=NAVY, fontsize=9)
    cbar.ax.tick_params(colors=SLATE, labelsize=8)
    cbar.outline.set_edgecolor(BORDER)

    ax.set_xlabel('Variables / columns', color=NAVY)
    ax.set_ylabel('Constraints / rows', color=NAVY)
    binned_note = f' · binned into {bins_r}×{bins_c} cells' if (bins_r < m or bins_c < n) else ''
    ax.set_title(
        f'Constraint Matrix A — Sparsity Density  ·  {m:,} × {n:,}  ·  '
        f'{nnz:,} non-zero terms ({problem.sparsity*100:.2f}% sparse){binned_note}',
        loc='left', color=NAVY, fontweight='bold', pad=12
    )

    def _ticks(total, count=8):
        if total <= 1:
            return [0], ['0']
        vals = np.linspace(0, total - 1, min(count, total), dtype=int)
        return vals, [f'{int(v)+1:,}' for v in vals]

    xt, xl = _ticks(n)
    yt, yl = _ticks(m)
    ax.set_xticks(xt); ax.set_xticklabels(xl)
    ax.set_yticks(yt); ax.set_yticklabels(yl)
    ax.tick_params(colors=SLATE, labelsize=8)
    for sp in ax.spines.values():
        sp.set_color(BORDER)
    ax.set_facecolor('white')
    fig.patch.set_facecolor('white')
    fig.tight_layout()
    st.pyplot(fig, use_container_width=True)
    plt.close(fig)

    st.caption(
        f"Each cell aggregates a block of the {m:,}×{n:,} matrix; darker = more of the "
        f"{nnz:,} actual non-zero entries fall in that block. This is a binned view of the "
        "real constraint matrix — no values are invented or estimated."
    )


def render_bottleneck_graph(timing_breakdown: dict):
    items=[(str(k),float(v)) for k,v in (timing_breakdown or {}).items() if np.isfinite(float(v)) and float(v)>0]
    if not items:
        st.markdown("<div class='cc-panel'><b>Instrumentation unavailable</b><div class='cc-muted'>No measured timing breakdown was returned by the solver.</div></div>",unsafe_allow_html=True); return
    if not _HAVE_MPL:
        st.bar_chart({k:v for k,v in items})
        return
    items.sort(key=lambda x:x[1]); labels=[x[0] for x in items]; vals=np.array([x[1]*1000 for x in items]); total=vals.sum(); pcts=vals/total*100
    fig,ax=plt.subplots(figsize=(11,max(2.8,0.55*len(items)+1.1)))
    bars=ax.barh(labels,vals,color=ROYAL_BLUE,alpha=.9,height=.58)
    ax.set_xlabel('Measured time (ms)',color=NAVY); ax.set_title('Measured GPU solver timing breakdown',loc='left',color=NAVY,fontweight='bold',pad=12)
    ax.grid(True,axis='x',alpha=.16); ax.set_axisbelow(True); ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False); ax.spines['left'].set_color(BORDER); ax.spines['bottom'].set_color(BORDER); ax.tick_params(colors=SLATE,labelsize=8)
    for b,p in zip(bars,pcts): ax.text(b.get_width(),b.get_y()+b.get_height()/2,f'  {p:.1f}%',va='center',fontsize=8,color=NAVY)
    fig.patch.set_facecolor('white'); ax.set_facecolor('white'); fig.tight_layout(); st.pyplot(fig,use_container_width=True); plt.close(fig)
    lead=labels[-1]
    st.markdown(f"<div class='cc-muted' style='margin-top:-.4rem'>Leading measured cost: <b style='color:{NAVY}'>{_html.escape(lead)}</b>. This is based on measured timing, not an estimate.</div>",unsafe_allow_html=True)


def render_speedup_reveal(cpu_time: float, gpu_time: float):
    speedup = cpu_time / gpu_time if gpu_time > 0 else float("nan")
    max_bar = 260
    gpu_bar = max_bar if cpu_time <= gpu_time else max(max_bar * (gpu_time / cpu_time), 8)
    html = f"""
    <div style="font-family:Inter,sans-serif;">
      <div style="display:flex; flex-direction:column; gap:10px; margin-bottom:14px;">
        <div>
          <div style="font-size:0.78rem; color:{SLATE}; font-weight:700; margin-bottom:3px;">CPU &middot; {cpu_time*1000:.2f} ms</div>
          <div style="height:16px; width:0px; background:{SLATE}; border-radius:4px; transition:width 1s ease-out;"
               id="cpubar"></div>
        </div>
        <div>
          <div style="font-size:0.78rem; color:{ROYAL_BLUE}; font-weight:700; margin-bottom:3px;">GPU &middot; {gpu_time*1000:.2f} ms</div>
          <div style="height:16px; width:0px; background:linear-gradient(90deg,{ROYAL_BLUE},{VIOLET});
               border-radius:4px; transition:width 1s ease-out;" id="gpubar"></div>
        </div>
      </div>
      <div id="speedup" style="text-align:center; font-size:2.1rem; font-weight:800; color:{NAVY};
           opacity:0; transform:scale(0.9); transition:opacity .5s, transform .5s, text-shadow .5s;">
        {speedup:.2f}&times; <span style="font-size:1.1rem; color:{SLATE}; font-weight:700;">FASTER</span>
      </div>
    </div>
    <script>
      setTimeout(() => {{
        document.getElementById('cpubar').style.width = '{max_bar}px';
        document.getElementById('gpubar').style.width = '{gpu_bar}px';
      }}, 80);
      setTimeout(() => {{
        const s = document.getElementById('speedup');
        s.style.opacity = 1; s.style.transform = 'scale(1.04)';
        s.style.textShadow = '0 0 18px rgba(41,85,214,0.25)';
        setTimeout(() => {{ s.style.transform = 'scale(1)'; }}, 200);
      }}, 700);
    </script>
    """
    components.html(html, height=190)
    return speedup


