def page_gpu_exec():
    problem: LPProblem = st.session_state.problem
    render_navbar("gpu_exec")
    stage_header("GPU EXECUTION", "PDHG Solver Running", "gpu_exec")
    if problem is None:
        st.warning("Load a problem first (Home).")
        return

    cfg = st.session_state.cfg
    info = gpu_static_info()

    if st.session_state.gpu_result is None:
        st.markdown("<div class='cc-exec-badge'><span class='cc-revolve-ring'></span>GPU EXECUTION IN PROGRESS</div>", unsafe_allow_html=True)
        status = st.empty(); loop_slot = st.empty(); progress = st.progress(0.0); iter_label = st.empty()
        _loop_pace = {"last": 0.0}
        def cb(it, max_it, rp, rd):
            frac=it/max_it
            progress.progress(min(frac,1.0))
            iter_label.markdown(f"**{it:,} / {max_it:,}** iterations  ·  primal residual `{rp:.3e}`  ·  dual residual `{rd:.3e}`")
            # Throttle the stage-highlight animation to a human-readable
            # cadence -- the solver itself runs at full, unthrottled speed;
            # only how often we redraw this small widget is paced.
            now = time.perf_counter()
            if it == 1 or (now - _loop_pace["last"]) >= 0.16:
                _loop_pace["last"] = now
                with loop_slot.container(): render_pdhg_loop(it,max_it,running=True)
        status.info("PDHG SOLVER RUNNING…")
        device="gpu" if _HAVE_CUPY else "cpu"
        if not _HAVE_CUPY:
            status.warning("CuPy / CUDA device not detected — this run is using the reference CPU execution path. Values shown below are from the actual run.")
        util_holder={"samples":[]}
        def sample_thread(): util_holder["samples"]=sample_gpu_utilization(duration_s=min(3.0,.5))
        t=threading.Thread(target=sample_thread,daemon=True); t.start()
        # Prefer the real compiled pipeline (mps_to_txt.py -> gpu_solver ->
        # cpu_solve.py) when the actual solver binary is present; then a
        # best-effort generic Python callable; then the NumPy/CuPy
        # reference implementation. Each step falls back honestly.
        _pipeline = run_real_solver_pipeline(
            problem, tol=cfg["tol"], max_iter=cfg["max_iter"],
            mps_text=st.session_state.get('_uploaded_mps'),
            csv_text=st.session_state.get('_uploaded_csv'),
        )
        if _pipeline is not None:
            result, _real_cpu_result = _pipeline
            if _real_cpu_result is not None:
                st.session_state.cpu_result = _real_cpu_result
        else:
            result=try_real_gpu_solve(problem,tol=cfg["tol"],max_iter=cfg["max_iter"])
            if result is None:
                result=reference_pdhg(problem,tol=cfg["tol"],max_iter=cfg["max_iter"],device=device,progress_cb=cb)
        t.join(timeout=.1)
        st.session_state.gpu_result=result; st.session_state.gpu_util_samples=util_holder["samples"]
        progress.progress(1.0)
        # A slow, clearly visible settle pass through all five PDHG stages --
        # purely cosmetic pacing after the real, already-measured solve has
        # finished; it does not touch result.elapsed or any other measured
        # value, so nothing shown anywhere else is affected by it.
        for _settle_i in range(len(["A · ȳ","DUAL UPDATE","Aᵀ · x","PRIMAL UPDATE","CONVERGENCE CHECK"])):
            with loop_slot.container(): render_pdhg_loop(_settle_i*3, result.max_iterations, running=True)
            time.sleep(0.38)
        loop_slot.empty(); status.success("✓ PDHG CONVERGED" if result.converged else "PDHG stopped at maximum iterations"); st.rerun()
    else:
        result: SolveResult=st.session_state.gpu_result
        st.success("✓ PDHG CONVERGED" if result.converged else "PDHG reached the maximum iteration limit before satisfying tolerance.")

        # Row 1 -- device identity. Row 2 -- the three PDHG convergence
        # numbers, same box size, same 3-column layout as row 1, so the two
        # rows read as one consistent grid. Everything below that (the
        # graphs) then gets the FULL page width instead of being squeezed
        # into a side column.
        mem=info.get("Memory",info.get("GPU Memory",info.get("Memory Total","Not available")))
        gpu_name=info.get("GPU",info.get("Device",info.get("Name","Not available")))
        render_metric_boxes([
            {"label":"GPU DEVICE","value":gpu_name,"detail":f"Execution: {result.device}","kind":"gpu"},
            {"label":"GPU MEMORY","value":mem,"detail":"Reported by the detected CUDA device","kind":"gpu"},
            {"label":"GPU SOLVE TIME","value":f"{result.elapsed*1000:.2f} ms","detail":f"{result.iterations:,} iterations","kind":"gpu"},
        ])
        primal_val = (result.history_primal[-1] if result.history_primal
                      else result.final_primal_residual)
        dual_val = (result.history_dual[-1] if result.history_dual
                    else result.final_dual_residual)
        render_metric_boxes([
            {"label":"PRIMAL RESIDUAL","value":f"{primal_val:.3e}" if primal_val is not None else "Not available","detail":"Final measured value","kind":"gpu"},
            {"label":"DUAL RESIDUAL","value":f"{dual_val:.3e}" if dual_val is not None else "Not available","detail":"Final measured value","kind":"gpu"},
            {"label":"OBJECTIVE","value":f"{result.objective:.6g}","detail":problem.sense.upper(),"kind":"gpu"},
        ])

        st.markdown("<div class='cc-panel-heading' style='margin-top:1rem'>PDHG CONVERGENCE</div>",unsafe_allow_html=True)
        render_pdhg_loop(result.iterations,result.max_iterations,running=False)
        if result.history_primal:
            st.markdown("<div class='cc-graph-heading'>Primal residual vs. iteration</div>",unsafe_allow_html=True)
            st.markdown("<div class='cc-graph-explain'>How far the current solution is from satisfying A x ≤ b. X-axis: recorded iteration point. Y-axis: primal residual (log scale) — should trend toward zero as PDHG converges.</div>",unsafe_allow_html=True)
            render_iteration_graph(result.history_primal,"Primal residual",color=ROYAL_BLUE,log_scale=True,height=280)
            if result.history_dual:
                st.markdown("<div class='cc-graph-heading'>Dual residual vs. iteration</div>",unsafe_allow_html=True)
                st.markdown("<div class='cc-graph-explain'>How far the dual variables are from optimality. X-axis: recorded iteration point. Y-axis: dual residual (log scale) — also trends toward zero at convergence.</div>",unsafe_allow_html=True)
                render_iteration_graph(result.history_dual,"Dual residual",color=VIOLET,log_scale=True,height=280)
            if result.history_obj:
                st.markdown("<div class='cc-graph-heading'>Objective value vs. iteration</div>",unsafe_allow_html=True)
                st.markdown("<div class='cc-graph-explain'>The LP objective evaluated at each recorded iteration's current solution. X-axis: recorded iteration point. Y-axis: objective value — settles as the solver converges.</div>",unsafe_allow_html=True)
                render_iteration_graph(result.history_obj,"Objective value",color=GREEN,log_scale=False,height=280)
        else:
            st.markdown("<div class='cc-muted'>No convergence history recorded for this run.</div>",unsafe_allow_html=True)

        st.markdown("**CUDA implementation**")
        if "real backend" in result.device:
            impl = ["cuSPARSE sparse matrix-vector products (CSR/CSC)",
                    "cuBLAS primal / dual vector updates",
                    f"Compiled solver: {result.device}"]
        else:
            impl=["CSR sparse matrix-vector products", "Primal / dual vector updates"]
            impl.append("CuPy CUDA kernels (device execution)" if _HAVE_CUPY else "NumPy reference kernels (CUDA unavailable)")
        st.markdown("<br>".join("• "+_html.escape(x) for x in impl),unsafe_allow_html=True)

        st.markdown("<div class='cc-primary' style='margin-top:1rem'>",unsafe_allow_html=True)
        if st.button("Continue to CPU Benchmark →",use_container_width=True): st.session_state.page="cpu_bench"; st.rerun()
        st.markdown("</div>",unsafe_allow_html=True)


