def page_cpu_bench():
    problem: LPProblem=st.session_state.problem
    render_navbar("cpu_bench")
    stage_header("CPU BENCHMARK","Same Problem, CPU Execution","cpu_bench")
    if problem is None or st.session_state.gpu_result is None:
        st.warning("Run GPU Execution first."); return
    cfg=st.session_state.cfg; cinfo=cpu_info()
    if st.session_state.cpu_result is None:
        with st.spinner("Solving the exact same LP on CPU (SciPy HiGHS)…"):
            real_cpu_result=try_real_cpu_solve(problem,tol=cfg["tol"],max_iter=cfg["max_iter"])
            st.session_state.cpu_result=real_cpu_result if real_cpu_result is not None else reference_cpu_solve(problem,tol=cfg["tol"],max_iter=cfg["max_iter"])
        st.rerun()
    cpu_res: SolveResult=st.session_state.cpu_result; gpu_res: SolveResult=st.session_state.gpu_result

    cpu_name=cinfo.get("CPU",cinfo.get("Processor",cinfo.get("Name","Not available")))
    cores=cinfo.get("Cores",cinfo.get("Physical cores",cinfo.get("Threads","Not available")))

    st.markdown("<div class='cc-graph-heading'>Same LP, two independent solvers</div>",unsafe_allow_html=True)
    st.markdown("<div class='cc-graph-explain'>The CPU section below ran SciPy's HiGHS solver; the GPU section ran the PDHG solver — both against the exact matrix parsed on the Input page.</div>",unsafe_allow_html=True)

    st.markdown("<div class='cc-device-section cpu'><div class='cc-device-section-title'><span class='cc-device-dot'></span>CPU — HOST EXECUTION</div>",unsafe_allow_html=True)
    render_metric_boxes([
        {"label":"CPU DEVICE","value":cpu_name,"detail":"Host processor","kind":"cpu"},
        {"label":"CPU SOLVE TIME","value":f"{cpu_res.elapsed*1000:.2f} ms","detail":f"{cpu_res.iterations:,} iterations" if cpu_res.iterations>=0 else "Iterations not reported","kind":"cpu"},
        {"label":"CPU CORES / THREADS","value":cores,"detail":"Reported by the host system","kind":"cpu"},
    ])
    render_metric_boxes([
        {"label":"ALGORITHM","value":"HiGHS","detail":"SciPy linprog","kind":"cpu"},
        {"label":"PRECISION","value":str(cpu_res.precision),"detail":f"Tolerance {cfg['tol']:.0e}","kind":"cpu"},
        {"label":"OBJECTIVE","value":f"{cpu_res.objective:.6g}","detail":problem.sense.upper(),"kind":"cpu"},
    ])
    st.markdown("</div>",unsafe_allow_html=True)

    st.markdown("<div class='cc-device-section gpu'><div class='cc-device-section-title'><span class='cc-device-dot'></span>GPU — DEVICE EXECUTION</div>",unsafe_allow_html=True)
    render_metric_boxes([
        {"label":"GPU SOLVE TIME","value":f"{gpu_res.elapsed*1000:.2f} ms","detail":gpu_res.device,"kind":"gpu"},
        {"label":"GPU ITERATIONS","value":f"{gpu_res.iterations:,}","detail":f"of {gpu_res.max_iterations:,} max","kind":"gpu"},
        {"label":"OBJECTIVE","value":f"{gpu_res.objective:.6g}","detail":problem.sense.upper(),"kind":"gpu"},
    ])
    render_metric_boxes([
        {"label":"ALGORITHM","value":"PDHG","detail":"Primal-Dual Hybrid Gradient","kind":"gpu"},
        {"label":"PRECISION","value":str(gpu_res.precision),"detail":"On-device arithmetic","kind":"gpu"},
        {"label":"TOLERANCE","value":f"{cfg['tol']:.0e}","detail":f"Max iterations {cfg['max_iter']:,}","kind":"gpu"},
    ])
    st.markdown("</div>",unsafe_allow_html=True)

    speedup=render_speedup_hero(cpu_res.elapsed,gpu_res.elapsed)
    # Proportional measured execution-time bars.
    render_speedup_reveal(cpu_res.elapsed,gpu_res.elapsed)

    st.markdown("#### Solution Validation")
    if np.isfinite(cpu_res.objective) and np.isfinite(gpu_res.objective):
        rel_diff=abs(cpu_res.objective-gpu_res.objective)/max(1.0,abs(cpu_res.objective))
        if rel_diff<1e-2: st.success(f"✓ SOLUTIONS CONSISTENT · relative difference {rel_diff:.2e}")
        else: st.warning(f"⚠ SOLUTION DIFFERENCE DETECTED · relative difference {rel_diff:.2e}")
    else: st.info("Solution comparison unavailable — one of the solves did not report a finite objective.")

    st.markdown("<div class='cc-primary' style='margin-top:1rem'>",unsafe_allow_html=True)
    if st.button("Continue to Analytics →",use_container_width=True): st.session_state.page="analytics"; st.rerun()
    st.markdown("</div>",unsafe_allow_html=True)


