def page_analytics():
    problem=st.session_state.problem
    render_navbar("analytics"); stage_header("VISUAL ANALYTICS","Measured performance and matrix behaviour","analytics")
    if problem is None or st.session_state.gpu_result is None or st.session_state.cpu_result is None:
        st.warning("Run GPU Execution and CPU Benchmark first."); return
    gpu_res=st.session_state.gpu_result; cpu_res=st.session_state.cpu_result
    speedup=cpu_res.elapsed/gpu_res.elapsed if gpu_res.elapsed>0 else float("nan")

    st.markdown("<div class='cc-section'>01 · Solver performance</div>",unsafe_allow_html=True)
    render_metric_boxes([
        {"label":"CPU SOLVE TIME","value":f"{cpu_res.elapsed*1000:.2f} ms","detail":"Same LP · CPU baseline","kind":"cpu"},
        {"label":"GPU SOLVE TIME","value":f"{gpu_res.elapsed*1000:.2f} ms","detail":f"PDHG · {gpu_res.iterations:,} iterations","kind":"gpu"},
        {"label":"OBJECTIVE","value":f"{gpu_res.objective:.6g}","detail":problem.sense.upper(),"kind":"gpu"},
    ])
    render_speedup_hero(cpu_res.elapsed,gpu_res.elapsed); render_speedup_reveal(cpu_res.elapsed,gpu_res.elapsed)

    st.markdown("<div class='cc-section'>02 · Explore the measured analysis</div>",unsafe_allow_html=True)
    st.markdown("<div class='cc-analysis-intro'>Select one analysis at a time — the chart below updates to match, keeping the page focused while every required graph stays one tap away.</div>",unsafe_allow_html=True)
    options=[("convergence","Convergence","PDHG iteration points"),("heatmap","Matrix Heat Map","Constraint sparsity"),("bottleneck","Bottleneck","Measured timing"),("utilization","GPU Utilization","Telemetry samples"),("comparison","CPU vs GPU","Final comparison")]
    if "analytics_view" not in st.session_state: st.session_state.analytics_view="heatmap"
    st.markdown("<div class='cc-pill-row'>",unsafe_allow_html=True)
    cols=st.columns(len(options))
    for col,(key,title,hint) in zip(cols,options):
        with col:
            active=st.session_state.analytics_view==key
            if st.button(title,key=f"analytics_{key}",use_container_width=True,
                         type="primary" if active else "secondary"):
                st.session_state.analytics_view=key; st.rerun()
            # Always-visible caption instead of a hover-only tooltip -- the
            # description should be readable without moving the cursor.
            st.markdown(f"<div class='cc-pill-caption{' active' if active else ''}'>{_html.escape(hint)}</div>",unsafe_allow_html=True)
    st.markdown("</div>",unsafe_allow_html=True)

    view=st.session_state.analytics_view
    st.markdown("<div class='cc-chart-shell'>",unsafe_allow_html=True)
    if view=="convergence":
        st.markdown("**PDHG convergence — recorded iteration points**")
        if gpu_res.history_primal: render_iteration_graph(gpu_res.history_primal,"Primal residual",color=ROYAL_BLUE,log_scale=True,height=350)
        else: st.info("Iteration history unavailable.")
    elif view=="heatmap":
        st.markdown("**Actual constraint matrix sparsity pattern**")
        render_sparsity_heatmap(problem,height=430)
    elif view=="bottleneck":
        st.markdown("**Measured GPU solver timing breakdown**")
        render_bottleneck_graph(gpu_res.timing_breakdown)
    elif view=="utilization":
        st.markdown("**GPU resource utilization**")
        samples=st.session_state.gpu_util_samples
        if samples: render_iteration_graph(samples,"GPU utilization (%)",log_scale=False,height=350)
        else: st.info("Telemetry unavailable — no live nvidia-smi utilization samples were captured. The UI does not fabricate utilization.")
    else:
        st.markdown("**CPU vs GPU — exact same LP**")
        st.dataframe({"Execution":["CPU","GPU"],"Solve Time":[f"{cpu_res.elapsed*1000:.2f} ms",f"{gpu_res.elapsed*1000:.2f} ms"],"Iterations":[cpu_res.iterations if cpu_res.iterations>=0 else "Not available",gpu_res.iterations],"Objective":[f"{cpu_res.objective:.6g}",f"{gpu_res.objective:.6g}"],"Precision":[cpu_res.precision,gpu_res.precision],"Speedup":["1.00×",f"{speedup:.2f}×" if np.isfinite(speedup) else "Not available"]},use_container_width=True,hide_index=True)
    st.markdown("</div>",unsafe_allow_html=True)

    st.markdown("<div class='cc-primary' style='margin-top:1rem'>",unsafe_allow_html=True)
    if st.button("View Final Results →",use_container_width=True): st.session_state.page="results"; st.rerun()
    st.markdown("</div>",unsafe_allow_html=True)


