def page_results():
    problem: LPProblem = st.session_state.problem
    render_navbar("results")
    stage_header("RESULTS", "Optimization Complete", "results")
    if problem is None or st.session_state.gpu_result is None or st.session_state.cpu_result is None:
        st.warning("Run GPU Execution and CPU Benchmark first.")
        return

    gpu_res: SolveResult = st.session_state.gpu_result
    cpu_res: SolveResult = st.session_state.cpu_result
    speedup = cpu_res.elapsed / gpu_res.elapsed if gpu_res.elapsed > 0 else float("nan")

    # 1 -- Objective: the strongest single result on this page.
    st.markdown(
        f"<div class='cc-result-hero'><div class='kicker'>{_html.escape(problem.sense.upper())} · OPTIMAL OBJECTIVE VALUE</div>"
        f"<div class='value'>{gpu_res.objective:.6g}</div>"
        f"<div class='note'>Verified against the independent CPU baseline below</div></div>",
        unsafe_allow_html=True,
    )

    # 2 -- GPU speedup: second-strongest, same glowing treatment used on the benchmark page.
    render_speedup_hero(cpu_res.elapsed, gpu_res.elapsed)

    # 3-4 -- CPU vs GPU solve time / iterations, in clearly differentiated device sections.
    st.markdown("<div class='cc-device-section cpu'><div class='cc-device-section-title'><span class='cc-device-dot'></span>CPU — HOST RESULT</div>",unsafe_allow_html=True)
    render_metric_boxes([
        {"label":"CPU SOLVE TIME","value":f"{cpu_res.elapsed*1000:.2f} ms","detail":cpu_res.device,"kind":"cpu"},
        {"label":"CPU ITERATIONS","value":f"{cpu_res.iterations:,}" if cpu_res.iterations>=0 else "Unavailable","detail":"HiGHS reported","kind":"cpu"},
        {"label":"CPU OBJECTIVE","value":f"{cpu_res.objective:.6g}","detail":cpu_res.precision,"kind":"cpu"},
    ])
    st.markdown("</div>",unsafe_allow_html=True)

    st.markdown("<div class='cc-device-section gpu'><div class='cc-device-section-title'><span class='cc-device-dot'></span>GPU — DEVICE RESULT</div>",unsafe_allow_html=True)
    render_metric_boxes([
        {"label":"GPU SOLVE TIME","value":f"{gpu_res.elapsed*1000:.2f} ms","detail":gpu_res.device,"kind":"gpu"},
        {"label":"GPU ITERATIONS","value":f"{gpu_res.iterations:,}","detail":f"of {gpu_res.max_iterations:,} max","kind":"gpu"},
        {"label":"GPU OBJECTIVE","value":f"{gpu_res.objective:.6g}","detail":gpu_res.precision,"kind":"gpu"},
    ])
    st.markdown("</div>",unsafe_allow_html=True)

    # 5-6 -- Remaining technical detail, lowest visual weight.
    with st.expander("Full CPU vs GPU comparison table"):
        st.dataframe(
            {
                "Execution": ["CPU", "GPU"],
                "Solve Time (ms)": [round(cpu_res.elapsed * 1000, 3), round(gpu_res.elapsed * 1000, 3)],
                "Iterations": [cpu_res.iterations if cpu_res.iterations >= 0 else "Unavailable", gpu_res.iterations],
                "Objective": [round(cpu_res.objective, 6), round(gpu_res.objective, 6)],
                "Precision": [cpu_res.precision, gpu_res.precision],
                "Speedup": ["1.00×", f"{speedup:.2f}×"],
            },
            use_container_width=True, hide_index=True,
        )

    rel_diff = abs(cpu_res.objective - gpu_res.objective) / max(1.0, abs(cpu_res.objective)) if np.isfinite(cpu_res.objective) and np.isfinite(gpu_res.objective) else None
    if rel_diff is not None:
        if rel_diff < 1e-2:
            st.success(f"✓ SOLUTIONS CONSISTENT (relative difference: {rel_diff:.2e})")
        else:
            st.warning(f"⚠ SOLUTION DIFFERENCE DETECTED (relative difference: {rel_diff:.2e})")

    with st.expander("Solution Vector"):
        st.dataframe(
            {"Variable": problem.var_names, "Value": np.round(gpu_res.x[: problem.n], 6)},
            use_container_width=True, hide_index=True,
        )

    c1, c2 = st.columns(2)
    with c1:
        if st.button("← Back to Analytics", use_container_width=True):
            st.session_state.page = "analytics"
            st.rerun()
    with c2:
        if st.button("Solve a New Problem", use_container_width=True):
            st.session_state.page = "home"
            st.session_state.problem = None
            st.session_state.gpu_result = None
            st.session_state.cpu_result = None
            st.session_state.validated = False
            st.rerun()


